#include <linux/eventpoll.h>
#include <linux/syscalls.h>
#include <linux/file.h>
#include <linux/fs.h>
#include <linux/poll.h>

int sys_epoll_ctl(int epfd, int op, int fd, struct epoll_event __user *event) {
    struct file *file, *f_ep;
    struct eventpoll *ep;
    int error;

    error = -EBADF;
    file = fget(fd);
    if (!file)
        goto error_return;

    f_ep = fget(epfd);
    if (!f_ep)
        goto error_fput_file;

    if (f_ep->f_op != &eventpoll_fops) {
        error = -EINVAL;
        goto error_fput_fep;
    }

    ep = f_ep->private_data;
    if (IS_ERR(ep)) {
        error = PTR_ERR(ep);
        goto error_fput_fep;
    }

    error = -EINVAL;
    if (op != EPOLL_CTL_ADD &&
        op != EPOLL_CTL_DEL &&
        op != EPOLL_CTL_MOD)
        goto error_fput_fep;

    mutex_lock(&ep->mtx);
    error = do_epoll_ctl(ep, ep, op, fd, event, 0);
    mutex_unlock(&ep->mtx);

error_fput_fep:
    fput(f_ep);
error_fput_file:
    fput(file);
error_return:
    return error;
}

int epoll_ctl(int epfd, int op, int fd, struct epoll_event __user *event) {
    struct file *file, *f;
    struct inode *inode;
    struct epoll *ep;
    int error = -EBADF;

    if (op != EPOLL_CTL_ADD && op != EPOLL_CTL_DEL && op != EPOLL_CTL_MOD)
        return -EINVAL;

    error = -EINVAL;
    if (op == EPOLL_CTL_DEL && !event)
        return -EINVAL;

    file = fget(epfd);
    if (!file)
        return -EBADF;

    inode = file->f_path.dentry->d_inode;
    if (!is_epoll(inode)) {
        fput(file);
        return -EINVAL;
    }

    ep = EPOLL(inode);
    mutex_lock(&ep->ep_mutex);

    f = fget(fd);
    if (!f) {
        mutex_unlock(&ep->ep_mutex);
        fput(file);
        return -EBADF;
    }

    if (f == file) {
        fput(f);
        mutex_unlock(&ep->ep_mutex);
        fput(file);
        return -EINVAL;
    }

    if (op == EPOLL_CTL_ADD) {
        error = epoll_add(ep, f, event);
    } else if (op == EPOLL_CTL_DEL) {
        error = epoll_del(ep, f);
    } else { /* EPOLL_CTL_MOD */
        error = epoll_mod(ep, f, event);
    }

    fput(f);
    mutex_unlock(&ep->ep_mutex);
    fput(file);
    return error;
}

