int handle_epoll_ctl(int epfd, int op, int fd, struct epoll_event __user *event) {
    struct file *ep_file, *target_file;
    struct inode *inode;
    int error = 0;

    if (op != EPOLL_CTL_ADD && op != EPOLL_CTL_DEL && op != EPOLL_CTL_MOD)
        return -EINVAL;

    if (fd == epfd)
        return -EINVAL;

    ep_file = fget(epfd);
    if (!ep_file) {
        return -EBADF;
    }

    target_file = fget(fd);
    if (!target_file) {
        fput(ep_file);
        return -EBADF;
    }

    if (!target_file->f_op || !target_file->f_op->poll) {
        fput(ep_file);
        fput(target_file);
        return -EINVAL;
    }

    inode = file_inode(ep_file);
    if (!S_ISDIR(inode->i_mode)) {
        fput(ep_file);
        fput(target_file);
        return -EINVAL;
    }

    mutex_lock(&ep_file->f_lock);

    switch (op) {
        case EPOLL_CTL_ADD:
            error = do_epoll_ctl(ep_file, op, fd, event);
            break;
        case EPOLL_CTL_DEL:
            error = do_epoll_ctl(ep_file, op, fd, event);
            break;
        case EPOLL_CTL_MOD:
            error = do_epoll_ctl(ep_file, op, fd, event);
            break;
    }

    mutex_unlock(&ep_file->f_lock);

    fput(ep_file);
    fput(target_file);

    return (error < 0) ? error : 0;
}

