#include <linux/eventpoll.h>
#include <linux/fs.h>
#include <linux/err.h>

int handle_epoll_ctl(int epfd, int op, int fd, struct epoll_event __user *event) {
    struct file *ep_file;
    struct file *target_file;

    if (epfd == fd)
        return -EINVAL;

    ep_file = fget(epfd);
    if (!ep_file)
        return -EBADF;

    if (!is_file_epoll(ep_file)) {
        fput(ep_file);
        return -EINVAL;
    }

    target_file = fget(fd);
    if (!target_file) {
        fput(ep_file);
        return -EBADF;
    }

    if (!target_file->f_op || !target_file->f_op->poll) {
        fput(ep_file);
        fput(target_file);
        return -EINVAL;
    }

    if (op == EPOLL_CTL_DEL) {
        mutex_lock(&ep_file->f_lock);
        int err = do_epoll_ctl(ep_file, op, fd, NULL);
        mutex_unlock(&ep_file->f_lock);
        fput(target_file);
        fput(ep_file);
        return err;
    }

    struct epoll_event e;
    if (copy_from_user(&e, event, sizeof(struct epoll_event))) {
        fput(ep_file);
        fput(target_file);
        return -EFAULT;
    }

    mutex_lock(&ep_file->f_lock);
    int err = do_epoll_ctl(ep_file, op, fd, &e);
    mutex_unlock(&ep_file->f_lock);

    fput(target_file);
    fput(ep_file);
    return err;
}
